Get Stock Out Report.code:
// Fetch the current stock-out report for the dispensing unit.
// state.data.items lists each item with onHand and daysOutOfStock.
get('DispensingUnit/Dashboard/StockOutReport');

Check Prescription.code:
// Check the status of a single prescription.
post(
  // 1) Path relative to the Dagu base URL.
  'Patient/CheckPrescription',
  // 2) Request body.
  { prescriptionRowGuid: $.data.prescriptionRowGuid }
);

Get Prescription History Page.code:
// Fetch the first 50 prescriptions from the history table.
post(
  'Patient/Prescription/History',
  {
    start: 0, // row offset
    length: 50, // page size
    draw: 1,
    additionalParameters: { filter: [] },
  },
  // 3) This endpoint expects multipart form data.
  { contentType: 'form' }
);

Get Dispensing Request History.code:
// List dispensing-unit request history.
request(
  // 1) HTTP method.
  'POST',
  // 2) Path relative to the Dagu base URL.
  'DispensingUnit/Request/History',
  // 3) Search criteria; an empty object returns all requests.
  { search: {} }
);
